//! Port of `ghidra.app.util.PseudoData`.
//!
//! The Java class is `"Fake" data generated by the PseudoDisassembler`. It extends
//! `PseudoCodeUnit` (an abstract, in-memory `CodeUnit` implementation, not yet ported) and
//! implements `Data`. Since [`Data`](crate::program::model::listing::data::Data) already
//! requires `CodeUnit` + `Settings` (which cover everything `PseudoCodeUnit` contributes), this
//! trait models `PseudoData` as a plain extension of `Data`, keeping it object-safe. This trait
//! was itself selected as a dependency-cycle cut-point; the constructors and `getComponent`
//! logic (which builds `PseudoDataComponent` instances) belong with whichever concrete type ends
//! up implementing this trait, once `PseudoDataComponent` is ported.

use crate::program::model::listing::data::Data;

/// "Fake" data generated by the PseudoDisassembler.
///
/// Port of `ghidra.app.util.PseudoData`.
pub trait PseudoData: Data {
    /// Returns a hex dump of the underlying bytes, e.g. `"01 02 ff"`.
    ///
    /// Port of `PseudoData.getByteCodeString()`.
    fn get_byte_code_string(&self) -> String {
        let mut bytes_str = String::new();
        for i in 0..self.get_length() {
            if i != 0 {
                bytes_str.push(' ');
            }
            match self.get_byte(i) {
                Ok(b) => bytes_str.push_str(&format!("{:02x}", b as u8)),
                Err(_) => bytes_str.push_str("??"),
            }
        }
        bytes_str
    }

    /// Port of `PseudoData.toString()`.
    fn to_display_string(&self) -> String {
        let mnemonic_string = self.get_mnemonic_string();
        let value_representation = self.get_default_value_representation();
        if value_representation.is_empty() {
            mnemonic_string
        } else {
            format!("{} {}", mnemonic_string, value_representation)
        }
    }
}

