    #[test]
    fn byte_code_string_and_display_string_use_real_bytes() {
        let data = MockPseudoData {
            bytes: vec![0x01, 0x02, 0xff],
        };
        let dyn_data: &dyn PseudoData = &data;

        assert_eq!(dyn_data.get_byte_code_string(), "01 02 ff");
        assert_eq!(dyn_data.to_display_string(), "?? 01 02 ff");
    }

